#!/usr/bin/env python3
"""Portfolio sync — runs in GitHub Actions when new photos land in
assets/incoming/<category>/.

For each incoming image:
  - bakes EXIF orientation into pixels (what you see = what the web shows)
  - writes 1600px web JPEG  -> assets/images/<category>-<NN>.jpg
  - writes 400px thumbnail   -> assets/images/<category>-<NN>-thumb.jpg
  - harvests embedded Title/Description -> js/artMeta.auto.js (3D card backs)
  - deletes the incoming file

Then rebuilds the gallery image lists in js/cubeGallery.js from the files
on disk (picks first, then numbered), and commits everything back.

Drop files into assets/incoming/<category>/ on github.com (or git push them).
Category folders: mixed-media, digital, photography, typography, street,
sketchbook. Anything else is skipped with a log line.
"""

import json
import os
import re
import sys

from PIL import Image, ImageOps

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
INCOMING = os.path.join(ROOT, "assets", "incoming")
IMGDIR = os.path.join(ROOT, "assets", "images")
JS_GALLERY = os.path.join(ROOT, "js", "cubeGallery.js")
JS_AUTO = os.path.join(ROOT, "js", "artMeta.auto.js")

CATEGORIES = ["mixed-media", "digital", "photography", "typography", "street", "sketchbook"]
IMG_EXTS = {".jpg", ".jpeg", ".png", ".webp"}


def optimize(src, dest):
    """EXIF-transpose first, then resize to 1600px max, save JPEG q82."""
    img = ImageOps.exif_transpose(Image.open(src))
    if img.mode != "RGB":
        img = img.convert("RGB")
    w, h = img.size
    if max(w, h) > 1600:
        r = 1600 / max(w, h)
        img = img.resize((int(w * r), int(h * r)), Image.LANCZOS)
    img.save(dest, "JPEG", quality=82, optimize=True)
    return img


def write_thumb(img, dest):
    """400px thumbnail next to the web file: X.jpg -> X-thumb.jpg."""
    w, h = img.size
    if max(w, h) > 400:
        r = 400 / max(w, h)
        img = img.resize((int(w * r), int(h * r)), Image.LANCZOS)
    base, _ = os.path.splitext(dest)
    img.save(f"{base}-thumb.jpg", "JPEG", quality=70, optimize=True)


def extract_meta(path):
    """Best-effort title/story from embedded metadata (PNG tEXt, EXIF, IPTC)."""
    meta = {}
    try:
        img = Image.open(path)
    except Exception:
        return meta
    try:
        info = dict(getattr(img, "info", {}) or {})
        try:
            txt = getattr(img, "text", None)
            if txt:
                info.update({k: str(v) for k, v in dict(txt).items()})
        except Exception:
            pass
        for key in ("Title", "title", "ObjectName", "objectname"):
            if info.get(key):
                meta["title"] = str(info[key]).strip()
                break
        for key in ("Description", "description", "Caption", "caption"):
            if info.get(key):
                meta["story"] = str(info[key]).strip()
                break
        try:
            exif = img.getexif()
            if not meta.get("title"):
                for tag in (270, 40091):  # ImageDescription, XPTitle
                    v = exif.get(tag)
                    if v:
                        if isinstance(v, bytes):
                            try:
                                v = v.decode("utf-16le", "ignore")
                            except Exception:
                                v = str(v)
                        meta["title"] = str(v).strip().strip("\x00")
                        break
        except Exception:
            pass
        try:
            from PIL.IptcImagePlugin import getiptcinfo
            iptc = getiptcinfo(img)
            if iptc:
                if not meta.get("title") and iptc.get((2, 5)):
                    meta["title"] = iptc[(2, 5)].decode("utf-8", "ignore").strip()
                if not meta.get("story") and iptc.get((2, 120)):
                    meta["story"] = iptc[(2, 120)].decode("utf-8", "ignore").strip()
        except Exception:
            pass
    except Exception:
        pass
    return {k: v for k, v in meta.items() if v}


def next_number(cat):
    nums = []
    for f in os.listdir(IMGDIR):
        m = re.match(re.escape(cat) + r"-(\d+)\.", f)
        if m and not f.endswith("-thumb.jpg"):
            nums.append(int(m.group(1)))
    return (max(nums) + 1) if nums else 1


def load_auto_meta():
    if not os.path.exists(JS_AUTO):
        return {}
    src = open(JS_AUTO).read()
    m = re.search(r"export const ART_META_AUTO = (\{.*\});", src, re.S)
    if not m:
        return {}
    try:
        return json.loads(m.group(1))
    except Exception:
        return {}


def save_auto_meta(auto):
    with open(JS_AUTO, "w") as fh:
        fh.write("// AUTO-GENERATED by portfolio-sync — do not edit by hand.\n")
        fh.write("// Your entries in artMeta.js override these.\n")
        fh.write("export const ART_META_AUTO = " + json.dumps(auto, indent=2, ensure_ascii=False) + ";\n")


def rebuild_galleries():
    """Rewrite each category's images[] in cubeGallery.js from the files
    on disk: picks first (sorted), then numbered (sorted numerically)."""
    src = open(JS_GALLERY).read()
    for cat in CATEGORIES:
        files = [f for f in os.listdir(IMGDIR)
                 if f.startswith(cat + "-") and not f.endswith("-thumb.jpg")
                 and os.path.splitext(f)[1].lower() in IMG_EXTS]
        picks = sorted([f for f in files if "pick" in f])
        numbered = sorted([f for f in files if "pick" not in f],
                          key=lambda f: int(re.search(r"-(\d+)\.", f).group(1)))
        ordered = picks + numbered
        arr = ", ".join(f"'{f}'" for f in ordered)
        pat = re.compile(r"(\{\s*id:\s*'" + re.escape(cat) +
                         r"'\s*,\s*label:\s*'[^']*'\s*,\s*images:\s*\[)[^\]]*(\]\s*\})")
        src, n = pat.subn(lambda m: m.group(1) + arr + m.group(2), src)
        assert n == 1, f"gallery pattern failed for {cat}"
    open(JS_GALLERY, "w").write(src)


def main():
    if not os.path.isdir(INCOMING):
        print("No assets/incoming/ directory — nothing to do.")
        return 0

    auto = load_auto_meta()
    processed = []
    skipped = []

    for cat in sorted(os.listdir(INCOMING)):
        catdir = os.path.join(INCOMING, cat)
        if not os.path.isdir(catdir) or cat.startswith("."):
            continue
        if cat not in CATEGORIES:
            skipped.append(f"{cat}/ (unknown category folder)")
            continue
        for name in sorted(os.listdir(catdir)):
            if name.startswith(".") or name == ".gitkeep":
                continue
            src = os.path.join(catdir, name)
            if not os.path.isfile(src):
                continue
            if os.path.splitext(name)[1].lower() not in IMG_EXTS:
                skipped.append(f"{cat}/{name} (not an image)")
                continue
            n = next_number(cat)
            pf = f"{cat}-{n:02d}.jpg"
            dest = os.path.join(IMGDIR, pf)
            try:
                meta = extract_meta(src)
                img = optimize(src, dest)
                write_thumb(img, dest)
            except Exception as ex:
                skipped.append(f"{cat}/{name} (unreadable: {ex})")
                continue
            if meta:
                auto[pf] = meta
            os.remove(src)
            processed.append(f"{cat}/{name} -> {pf}")

    if processed:
        rebuild_galleries()
        save_auto_meta(auto)

    print(f"Processed: {len(processed)}")
    for p in processed:
        print(f"  + {p}")
    if skipped:
        print(f"Skipped: {len(skipped)}")
        for s in skipped:
            print(f"  - {s}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
